WITH base AS (SELECT *, ROUND(DATEDIFF(start_date, end_date) / 30, 1) AS months_end_date_to_start_date FROM subscriptions WHERE monthly_fee > 190 OR customer_id = 11), summary AS (SELECT DATE_TRUNC('MONTH', start_date) AS start_month, COUNT(DISTINCT months_end_date_to_start_date) AS unique_statuss, COUNT(months_end_date_to_start_date) AS months_end_date_to_start_date_count FROM base GROUP BY DATE_TRUNC('MONTH', start_date)) SELECT start_month, unique_statuss, months_end_date_to_start_date_count FROM summary WHERE unique_statuss >= 3
